/// cmstypes residual — Type_*_Write internals on unusual
///   payloads for every writable tag type (date/measurement/
///   s15fixed16/u8fixed8/response16/screening).
#[test]
fn type_write8_arms() {
    unsafe {
        let srgb = c::cmsCreate_sRGBProfile();
        let g = c::cmsBuildGamma(std::ptr::null_mut(), 2.2);
        // measurement payload
        for sig in [0x6D656173u32] {
            let prof = c::cmsCreateProfilePlaceholder(std::ptr::null_mut());
            c::cmsSetDeviceClass(prof, 0x6D6E7472);
            c::cmsSetColorSpace(prof, 0x52474220);
            c::cmsSetPCS(prof, 0x58595A20);
            c::cmsSetProfileVersion(prof, 4.4);
            for (v, name) in [
                (0u32, "obs0"),
                (1, "obs1"),
                (2, "obs2"),
                (0xFFFFFFFF, "max"),
            ] {
                // cmsICCMeasurementConditions* = {u32
                //   Observer; XYZ Backing@8; u32 Geometry
                //   @32; f64 Flare@40; u32 Illuminant@48}
                #[repr(align(8))]
                struct MS {
                    b: [u8; 56],
                }
                let mut ms = MS { b: [0u8; 56] };
                let xyz = [0.5f64, 0.5, 0.5];
                {
                    *(ms.b.as_mut_ptr() as *mut u32) = v;
                    std::ptr::copy_nonoverlapping(
                        xyz.as_ptr(),
                        ms.b.as_mut_ptr().add(8) as *mut f64,
                        3,
                    );
                    *(ms.b.as_mut_ptr().add(32) as *mut u32) = v;
                    *(ms.b.as_mut_ptr().add(40) as *mut f64) = v as f64;
                    *(ms.b.as_mut_ptr().add(48) as *mut u32) = v;
                }
                let w = c::cmsWriteTag(prof, sig, ms.b.as_ptr() as *const _);
                let mut buf = vec![0u8; 1 << 20];
                let mut n = buf.len() as u32;
                let s = c::cmsSaveProfileToMem(prof, buf.as_mut_ptr() as *mut _, &mut n);
                eprintln!("{sig:#x} {name} w={w} s={s}");
            }
            c::cmsCloseProfile(prof);
        }
        // s15Fixed16 array payload
        for sig in [0x6C756D69u32, 0x626B7074] {
            let prof = c::cmsCreateProfilePlaceholder(std::ptr::null_mut());
            c::cmsSetDeviceClass(prof, 0x6D6E7472);
            c::cmsSetColorSpace(prof, 0x52474220);
            c::cmsSetPCS(prof, 0x58595A20);
            c::cmsSetProfileVersion(prof, 4.4);
            for (n_, name) in [(1u32, "1"), (3, "3"), (16, "16")] {
                let xyzs: Vec<c::CieXyz> = (0..n_)
                    .map(|i| c::CieXyz {
                        X: i as f64 * 0.1,
                        Y: i as f64 * 0.1,
                        Z: i as f64 * 0.1,
                    })
                    .collect();
                let w = c::cmsWriteTag(prof, sig, xyzs.as_ptr() as *const _);
                let mut buf = vec![0u8; 1 << 20];
                let mut n = buf.len() as u32;
                let s = c::cmsSaveProfileToMem(prof, buf.as_mut_ptr() as *mut _, &mut n);
                eprintln!("{sig:#x} {name} w={w} s={s}");
            }
            c::cmsCloseProfile(prof);
        }
        // screening payload
        for sig in [0x7363726Eu32] {
            let prof = c::cmsCreateProfilePlaceholder(std::ptr::null_mut());
            c::cmsSetDeviceClass(prof, 0x6D6E7472);
            c::cmsSetColorSpace(prof, 0x52474220);
            c::cmsSetPCS(prof, 0x58595A20);
            c::cmsSetProfileVersion(prof, 4.4);
            for (n_, name) in [(0u32, "flag0"), (1, "flag1"), (0xFFFFFFFF, "max")] {
                // cmsScreening* = { u32 flag; u32 nChannels;
                //   cmsScreeningChannel ch[16] } where
                //   ch = {f64 freq; f64 angle; u32 spot}
                #[repr(align(8))]
                struct SC {
                    b: [u8; 8 + 16 * 24],
                }
                let mut sc = SC {
                    b: [0u8; 8 + 16 * 24],
                };
                {
                    *(sc.b.as_mut_ptr() as *mut u32) = n_;
                    *(sc.b.as_mut_ptr().add(4) as *mut u32) = 4;
                    for i in 0..16 {
                        let d = sc.b.as_mut_ptr().add(8 + i * 24);
                        *(d as *mut f64) = 60.0 + i as f64;
                        *(d.add(8) as *mut f64) = 15.0 + i as f64;
                        *(d.add(16) as *mut u32) = i as u32;
                    }
                }
                let w = c::cmsWriteTag(prof, sig, sc.b.as_ptr() as *const _);
                let mut buf = vec![0u8; 1 << 20];
                let mut n = buf.len() as u32;
                let s = c::cmsSaveProfileToMem(prof, buf.as_mut_ptr() as *mut _, &mut n);
                eprintln!("{sig:#x} {name} w={w} s={s}");
            }
            c::cmsCloseProfile(prof);
        }
        // response16 payload
        for sig in [0x73696763u32] {
            let prof = c::cmsCreateProfilePlaceholder(std::ptr::null_mut());
            c::cmsSetDeviceClass(prof, 0x6D6E7472);
            c::cmsSetColorSpace(prof, 0x52474220);
            c::cmsSetPCS(prof, 0x58595A20);
            c::cmsSetProfileVersion(prof, 4.4);
            for (n_, name) in [(1u32, "1"), (4, "4"), (16, "16")] {
                // cmsSigResponse16Type = { u8 sig[4];
                //   u32 nChannels; u16 resp[] } — payload
                //   is cmsResponse16 struct not raw
                #[repr(align(4))]
                struct RS {
                    b: [u8; 16],
                }
                let mut rs = RS { b: [0u8; 16] };
                rs.b[0] = b't';
                rs.b[1] = b'e';
                rs.b[2] = b's';
                rs.b[3] = b't';
                {
                    *(rs.b.as_mut_ptr().add(4) as *mut u32) = n_;
                }
                let w = c::cmsWriteTag(prof, sig, rs.b.as_ptr() as *const _);
                let mut buf = vec![0u8; 1 << 20];
                let mut n = buf.len() as u32;
                let s = c::cmsSaveProfileToMem(prof, buf.as_mut_ptr() as *mut _, &mut n);
                eprintln!("{sig:#x} {name} w={w} s={s}");
            }
            c::cmsCloseProfile(prof);
        }
        c::cmsCloseProfile(srgb);
        c::cmsFreeToneCurve(g);
    }
}

