/// cmstypes residual — Type_*_Write internals on unusual
///   payloads for every writable tag type (matrix/
///   s15fixed16-scalar/u8fixed8-scalar/curve-extrapolated).
#[test]
fn type_write15_arms() {
    unsafe {
        let srgb = c::cmsCreate_sRGBProfile();
        let g = c::cmsBuildGamma(std::ptr::null_mut(), 2.2);
        // matrix payload on chad
        for sig in [0x63686164u32] {
            let prof = c::cmsCreateProfilePlaceholder(std::ptr::null_mut());
            c::cmsSetDeviceClass(prof, 0x6D6E7472);
            c::cmsSetColorSpace(prof, 0x52474220);
            c::cmsSetPCS(prof, 0x58595A20);
            c::cmsSetProfileVersion(prof, 4.4);
            for (v, name) in [
                (0.0f64, "zero"),
                (0.5, "half"),
                (1.0, "one"),
                (-1.0, "neg"),
                (1e6, "big"),
                (f64::NAN, "nan"),
                (f64::INFINITY, "inf"),
            ] {
                // s15Fixed16[9] = 9 doubles
                let mat = [v; 9];
                let w = c::cmsWriteTag(prof, sig, mat.as_ptr() as *const _);
                let mut buf = vec![0u8; 1 << 20];
                let mut n = buf.len() as u32;
                let s = c::cmsSaveProfileToMem(prof, buf.as_mut_ptr() as *mut _, &mut n);
                eprintln!("{sig:#x} {name} w={w} s={s}");
            }
            c::cmsCloseProfile(prof);
        }
        // extrapolated curves (x0<0, x1>1)
        for sig in [0x72545243u32, 0x67545243, 0x62545243] {
            let prof = c::cmsCreateProfilePlaceholder(std::ptr::null_mut());
            c::cmsSetDeviceClass(prof, 0x6D6E7472);
            c::cmsSetColorSpace(prof, 0x52474220);
            c::cmsSetPCS(prof, 0x58595A20);
            c::cmsSetProfileVersion(prof, 4.4);
            for ((x0, x1), name) in [
                ((-0.5f32, 0.5f32), "x-0.5"),
                ((0.0, 1.5), "x1.5"),
                ((-1.0, 2.0), "x-1+2"),
            ] {
                let seg = c::CurveSegment {
                    x0,
                    x1,
                    r#type: 6,
                    params: [1.0; 10],
                    n_grid_points: 4,
                    sampled_points: [0.25f32, 0.5, 0.75, 1.0].as_ptr(),
                };
                let samples = [0.25f32, 0.5, 0.75, 1.0];
                let mut seg_ = seg;
                seg_.sampled_points = samples.as_ptr();
                let tc = c::cmsBuildSegmentedToneCurve(std::ptr::null_mut(), 1, &seg_);
                let w = if !tc.is_null() {
                    c::cmsWriteTag(prof, sig, tc as *const _)
                } else {
                    0
                };
                let mut buf = vec![0u8; 1 << 20];
                let mut n = buf.len() as u32;
                let s = c::cmsSaveProfileToMem(prof, buf.as_mut_ptr() as *mut _, &mut n);
                eprintln!("{sig:#x} {name} w={w} s={s}");
                if !tc.is_null() {
                    c::cmsFreeToneCurve(tc);
                }
            }
            c::cmsCloseProfile(prof);
        }
        c::cmsCloseProfile(srgb);
        c::cmsFreeToneCurve(g);
    }
}

