/// cmstypes residual — Type_*_Write internals on unusual
///   payloads for every writable tag type (u8fixed8/
///   u16fixed16/s15fixed16/ufixed64/int8/int16/int32/int64).
#[test]
fn type_write22_arms() {
    unsafe {
        let srgb = c::cmsCreate_sRGBProfile();
        let g = c::cmsBuildGamma(std::ptr::null_mut(), 2.2);
        // int array payloads via data sigs on every type
        for sig in [
            0x70736430u32,
            0x70736431,
            0x70736432,
            0x70736433,
            0x70733273,
            0x70733269,
            0x70733265,
            0x6261636B,
        ] {
            let prof = c::cmsCreateProfilePlaceholder(std::ptr::null_mut());
            c::cmsSetDeviceClass(prof, 0x6D6E7472);
            c::cmsSetColorSpace(prof, 0x52474220);
            c::cmsSetPCS(prof, 0x58595A20);
            c::cmsSetProfileVersion(prof, 4.4);
            for (sz, name) in [
                (1usize, "1"),
                (2, "2"),
                (4, "4"),
                (8, "8"),
                (16, "16"),
                (256, "256"),
            ] {
                let mut d = vec![0u8; 12 + sz];
                d[0..4].copy_from_slice(&0u32.to_be_bytes());
                d[4..8].copy_from_slice(&(sz as u32).to_be_bytes());
                for i in 0..sz {
                    d[8 + i] = (i % 256) as u8;
                }
                let w = c::cmsWriteTag(prof, sig, d.as_ptr() as *const _);
                let mut buf = vec![0u8; 1 << 22];
                let mut n = buf.len() as u32;
                let s = c::cmsSaveProfileToMem(prof, buf.as_mut_ptr() as *mut _, &mut n);
                eprintln!("{sig:#x} {name} w={w} s={s}");
            }
            c::cmsCloseProfile(prof);
        }
        // s15Fixed16 scalar on XYZ sigs with edge values
        for sig in [
            0x77747074u32,
            0x7258595A,
            0x6758595A,
            0x6258595A,
            0x626B7074,
            0x6C756D69,
        ] {
            let prof = c::cmsCreateProfilePlaceholder(std::ptr::null_mut());
            c::cmsSetDeviceClass(prof, 0x6D6E7472);
            c::cmsSetColorSpace(prof, 0x52474220);
            c::cmsSetPCS(prof, 0x58595A20);
            c::cmsSetProfileVersion(prof, 4.4);
            for (x, name) in [
                (0.0f64, "z"),
                (0.5, "m"),
                (1.0, "1"),
                (-1.0, "n"),
                (32767.9999, "max"),
                (-32768.0, "min"),
                (f64::NAN, "nan"),
                (f64::INFINITY, "inf"),
                (-f64::INFINITY, "-inf"),
            ] {
                let xyz = c::CieXyz { X: x, Y: x, Z: x };
                let w = c::cmsWriteTag(prof, sig, &xyz as *const _ as *const _);
                let mut buf = vec![0u8; 1 << 20];
                let mut n = buf.len() as u32;
                let s = c::cmsSaveProfileToMem(prof, buf.as_mut_ptr() as *mut _, &mut n);
                eprintln!("{sig:#x} {name} w={w} s={s}");
            }
            c::cmsCloseProfile(prof);
        }
        c::cmsCloseProfile(srgb);
        c::cmsFreeToneCurve(g);
    }
}

