fn type_read23_arms() {
    unsafe {
        let srgb = c::cmsCreate_sRGBProfile();
        let g = c::cmsBuildGamma(std::ptr::null_mut(), 2.2);
        // write + read mft1 lut8 on v2
        for sig in [0x41324230u32, 0x42324130] {
            for (st, sname) in [(0u32, "clut8"), (1, "cv+clut8")] {
                let prof = c::cmsCreateProfilePlaceholder(std::ptr::null_mut());
                c::cmsSetDeviceClass(prof, 0x6D6E7472);
                c::cmsSetColorSpace(prof, 0x52474220);
                c::cmsSetPCS(prof, 0x58595A20);
                c::cmsSetProfileVersion(prof, 2.0);
                let p = c::cmsPipelineAlloc(std::ptr::null_mut(), 3, 3);
                let dims = [3u32; 3];
                let grid = [0x4000u16; 81];
                if st == 0 {
                    c::cmsPipelineInsertStage(
                        p,
                        0,
                        c::cmsStageAllocCLut16bitGranular(
                            std::ptr::null_mut(),
                            dims.as_ptr(),
                            3,
                            3,
                            grid.as_ptr(),
                        ),
                    );
                } else {
                    let trcs = [g, g, g];
                    c::cmsPipelineInsertStage(
                        p,
                        0,
                        c::cmsStageAllocToneCurves(
                            std::ptr::null_mut(),
                            3,
                            trcs.as_ptr() as *mut _,
                        ),
                    );
                    c::cmsPipelineInsertStage(
                        p,
                        1,
                        c::cmsStageAllocCLut16bitGranular(
                            std::ptr::null_mut(),
                            dims.as_ptr(),
                            3,
                            3,
                            grid.as_ptr(),
                        ),
                    );
                }
                let w = c::cmsWriteTag(prof, sig, p as *const _);
                let mut buf = vec![0u8; 1 << 20];
                let mut n = buf.len() as u32;
                let s = c::cmsSaveProfileToMem(prof, buf.as_mut_ptr() as *mut _, &mut n);
                let rp = if s != 0 {
                    c::cmsOpenProfileFromMem(buf.as_ptr() as *const _, n)
                } else {
                    std::ptr::null_mut()
                };
                let r = if !rp.is_null() {
                    let t = c::cmsReadTag(rp, sig);
                    let ok = !t.is_null();
                    c::cmsCloseProfile(rp);
                    ok
                } else {
                    false
                };
                eprintln!("{sig:#x} {sname} w={w} s={s} r={r}");
                c::cmsCloseProfile(prof);
                c::cmsPipelineFree(p);
            }
        }
        // write + read mixed-dim CLUTs
        for sig in [0x41324230u32] {
            let prof = c::cmsCreateProfilePlaceholder(std::ptr::null_mut());
            c::cmsSetDeviceClass(prof, 0x6D6E7472);
            c::cmsSetColorSpace(prof, 0x52474220);
            c::cmsSetPCS(prof, 0x58595A20);
            c::cmsSetProfileVersion(prof, 2.0);
            for (dims_, dname) in [([2u32, 3, 4], "2x3x4"), ([5u32, 5, 5], "5x5x5")] {
                let p = c::cmsPipelineAlloc(std::ptr::null_mut(), 3, 3);
                let ngrid = dims_[0] as usize * dims_[1] as usize * dims_[2] as usize * 3;
                let grid: Vec<u16> = (0..ngrid).map(|i| (i % 65536) as u16).collect();
                c::cmsPipelineInsertStage(
                    p,
                    0,
                    c::cmsStageAllocCLut16bitGranular(
                        std::ptr::null_mut(),
                        dims_.as_ptr(),
                        3,
                        3,
                        grid.as_ptr(),
                    ),
                );
                let w = c::cmsWriteTag(prof, sig, p as *const _);
                let mut buf = vec![0u8; 1 << 22];
                let mut n = buf.len() as u32;
                let s = c::cmsSaveProfileToMem(prof, buf.as_mut_ptr() as *mut _, &mut n);
                let rp = if s != 0 {
                    c::cmsOpenProfileFromMem(buf.as_ptr() as *const _, n)
                } else {
                    std::ptr::null_mut()
                };
                let r = if !rp.is_null() {
                    let t = c::cmsReadTag(rp, sig);
                    let ok = !t.is_null();
                    c::cmsCloseProfile(rp);
                    ok
                } else {
                    false
                };
                eprintln!("{sig:#x} {dname} w={w} s={s} r={r}");
                c::cmsPipelineFree(p);
            }
            c::cmsCloseProfile(prof);
        }
        c::cmsCloseProfile(srgb);
        c::cmsFreeToneCurve(g);
    }
}

