/// cmstypes residual — Type_*_Write internals on unusual
///   payloads for every writable tag type (text-desc/
///   text-mlu on all remaining sigs + response16-counts).
#[test]
fn type_write28_arms() {
    unsafe {
        let srgb = c::cmsCreate_sRGBProfile();
        let g = c::cmsBuildGamma(std::ptr::null_mut(), 2.2);
        // response16 on all channel counts
        for sig in [0x73696763u32] {
            let prof = c::cmsCreateProfilePlaceholder(std::ptr::null_mut());
            c::cmsSetDeviceClass(prof, 0x6D6E7472);
            c::cmsSetColorSpace(prof, 0x52474220);
            c::cmsSetPCS(prof, 0x58595A20);
            c::cmsSetProfileVersion(prof, 4.4);
            for (n_, name) in [
                (1u32, "1"),
                (4, "4"),
                (16, "16"),
                (255, "255"),
                (256, "256"),
                (4096, "4k"),
            ] {
                let mut d = vec![0u8; 8 + n_ as usize * 2];
                d[0..4].copy_from_slice(b"resp");
                d[4..8].copy_from_slice(&n_.to_ne_bytes());
                for i in 0..n_ as usize {
                    let v = (i * 0x10) as u16;
                    d[8 + i * 2..10 + i * 2].copy_from_slice(&v.to_ne_bytes());
                }
                let w = c::cmsWriteTag(prof, sig, d.as_ptr() as *const _);
                let mut buf = vec![0u8; 1 << 22];
                let mut n = buf.len() as u32;
                let s = c::cmsSaveProfileToMem(prof, buf.as_mut_ptr() as *mut _, &mut n);
                eprintln!("{sig:#x} {name} w={w} s={s}");
            }
            c::cmsCloseProfile(prof);
        }
        // multi-sig text-desc writes on all sigs
        for sig in [
            0x64657363u32,
            0x63707274,
            0x6D6E6672,
            0x6D646C20,
            0x74617267,
        ] {
            for (ver, name) in [(2.0f64, "v2"), (4.4, "v4")] {
                let prof = c::cmsCreateProfilePlaceholder(std::ptr::null_mut());
                c::cmsSetDeviceClass(prof, 0x6D6E7472);
                c::cmsSetColorSpace(prof, 0x52474220);
                c::cmsSetPCS(prof, 0x58595A20);
                c::cmsSetProfileVersion(prof, ver);
                for (txt, tname) in [(&b"a\0"[..], "1c"), (&b"abcdefghij\0"[..], "10c")] {
                    let w = write_text_like(prof, sig, txt);
                    let mut buf = vec![0u8; 1 << 20];
                    let mut n = buf.len() as u32;
                    let s = c::cmsSaveProfileToMem(prof, buf.as_mut_ptr() as *mut _, &mut n);
                    eprintln!(
                        "{sig:#x} {name} {tname} \
                        w={w} s={s}"
                    );
                }
                c::cmsCloseProfile(prof);
            }
        }
        c::cmsCloseProfile(srgb);
        c::cmsFreeToneCurve(g);
    }
}

