/// cmstypes residual — dict entries WITH display-name/
/// display-value MLUs (args 3-4 were NULL in every prior
/// gate) + MLU multi-locale + segmented-curve all types.
#[test]
fn type_write32_arms() {
    unsafe {
        let srgb = c::cmsCreate_sRGBProfile();
        let g = c::cmsBuildGamma(std::ptr::null_mut(), 2.2);
        // dict with display MLUs
        for sig in [0x6D657461u32] {
            let prof = c::cmsCreateProfilePlaceholder(std::ptr::null_mut());
            c::cmsSetDeviceClass(prof, 0x6D6E7472);
            c::cmsSetColorSpace(prof, 0x52474220);
            c::cmsSetPCS(prof, 0x58595A20);
            c::cmsSetProfileVersion(prof, 4.4);
            for (have_dn, have_dv, name) in [
                (true, true, "dn+dv"),
                (true, false, "dn"),
                (false, true, "dv"),
            ] {
                let dict = c::cmsDictAlloc(std::ptr::null_mut());
                for i in 0..4u32 {
                    let mut kw = [0i32; 8];
                    let mut vw = [0i32; 8];
                    let k = format!("k{i}\0");
                    let v = format!("v{i}\0");
                    for (j, b) in k.chars().enumerate() {
                        kw[j] = b as i32;
                    }
                    for (j, b) in v.chars().enumerate() {
                        vw[j] = b as i32;
                    }
                    let dn = if have_dn {
                        let m = c::cmsMLUalloc(std::ptr::null_mut(), 1);
                        let s_ = format!("dn{i}\0");
                        let mut w_ = [0i32; 8];
                        for (j, ch) in s_.chars().enumerate() {
                            w_[j] = ch as i32;
                        }
                        c::cmsMLUsetWide(
                            m,
                            c"en".as_ptr() as *const _,
                            c"US".as_ptr() as *const _,
                            w_.as_ptr(),
                        );
                        m
                    } else {
                        std::ptr::null_mut()
                    };
                    let dv = if have_dv {
                        let m = c::cmsMLUalloc(std::ptr::null_mut(), 1);
                        let s_ = format!("dv{i}\0");
                        let mut w_ = [0i32; 8];
                        for (j, ch) in s_.chars().enumerate() {
                            w_[j] = ch as i32;
                        }
                        c::cmsMLUsetWide(
                            m,
                            c"en".as_ptr() as *const _,
                            c"US".as_ptr() as *const _,
                            w_.as_ptr(),
                        );
                        m
                    } else {
                        std::ptr::null_mut()
                    };
                    c::cmsDictAddEntry(dict, kw.as_ptr(), vw.as_ptr(), dn, dv);
                }
                let w = c::cmsWriteTag(prof, sig, dict as *const _);
                let mut buf = vec![0u8; 1 << 20];
                let mut n = buf.len() as u32;
                let s = c::cmsSaveProfileToMem(prof, buf.as_mut_ptr() as *mut _, &mut n);
                eprintln!("{sig:#x} {name} w={w} s={s}");
                c::cmsDictFree(dict);
            }
            c::cmsCloseProfile(prof);
        }
        // MLU with many locale entries
        for sig in [0x64657363u32, 0x63707274] {
            let prof = c::cmsCreateProfilePlaceholder(std::ptr::null_mut());
            c::cmsSetDeviceClass(prof, 0x6D6E7472);
            c::cmsSetColorSpace(prof, 0x52474220);
            c::cmsSetPCS(prof, 0x58595A20);
            c::cmsSetProfileVersion(prof, 4.4);
            for (nl, name) in [(1u32, "1loc"), (4, "4loc"), (16, "16loc"), (64, "64loc")] {
                let mlu = c::cmsMLUalloc(std::ptr::null_mut(), nl);
                for i in 0..nl {
                    let s_ = format!("l{i}\0");
                    let mut w_ = [0i32; 8];
                    for (j, ch) in s_.chars().enumerate() {
                        w_[j] = ch as i32;
                    }
                    let lang = match i % 4 {
                        0 => c"en".as_ptr(),
                        1 => c"de".as_ptr(),
                        2 => c"fr".as_ptr(),
                        _ => c"ja".as_ptr(),
                    };
                    let ctry = match i % 4 {
                        0 => c"US".as_ptr(),
                        1 => c"DE".as_ptr(),
                        2 => c"FR".as_ptr(),
                        _ => c"JP".as_ptr(),
                    };
                    c::cmsMLUsetWide(mlu, lang as *const _, ctry as *const _, w_.as_ptr());
                }
                let w = c::cmsWriteTag(prof, sig, mlu as *const _);
                let mut buf = vec![0u8; 1 << 20];
                let mut n = buf.len() as u32;
                let s = c::cmsSaveProfileToMem(prof, buf.as_mut_ptr() as *mut _, &mut n);
                eprintln!("{sig:#x} {name} w={w} s={s}");
                c::cmsMLUfree(mlu);
            }
            c::cmsCloseProfile(prof);
        }
        c::cmsCloseProfile(srgb);
        c::cmsFreeToneCurve(g);
    }
}

