/// cmstypes residual — DupTagList/DupTagTypeList via
///   cmsDupContext on plugin-bearing contexts (tag/tagtype/
///   MPE plugin list duplication internals).
#[test]
fn type_write37_arms() {
    unsafe extern "C" fn decide_type(_v: f64, _d: *const std::ffi::c_void) -> u32 {
        0x63757276 // curv
    }
    unsafe {
        let srgb = c::cmsCreate_sRGBProfile();
        let g = c::cmsBuildGamma(std::ptr::null_mut(), 2.2);
        // plugin base = {u32 Magic; u32 ExpectedVersion;
        //   u32 Type; void* Next}
        #[repr(C)]
        #[derive(Clone, Copy)]
        struct PluginBase {
            magic: u32,
            ver: u32,
            typ: u32,
            next: *mut std::ffi::c_void,
        }
        #[repr(C)]
        struct TagPlugin {
            base: PluginBase,
            sig: u32,
            elem_count: u32,
            n_supported: u32,
            supported: [u32; 20],
            decide: *const std::ffi::c_void,
        }
        #[repr(C)]
        struct TagTypePlugin {
            base: PluginBase,
            // cmsTagTypeHandler: sig + read/write/dup/free
            //   fn ptrs + context + iccversion
            sig: u32,
            read: *const std::ffi::c_void,
            write: *const std::ffi::c_void,
            dup: *const std::ffi::c_void,
            free: *const std::ffi::c_void,
            ctx: *mut std::ffi::c_void,
            iccver: u32,
        }
        #[repr(C)]
        struct MpePlugin {
            base: PluginBase,
            sig: u32,
            n_in: u32,
            n_out: u32,
            eval: *const std::ffi::c_void,
            dup: *const std::ffi::c_void,
            free: *const std::ffi::c_void,
        }
        // register 4 plugins of each kind into a context
        for (npl, name) in [(1u32, "1each"), (4, "4each")] {
            let ctx = c::cmsCreateContext(std::ptr::null_mut(), std::ptr::null_mut());
            let mut tags: Vec<TagPlugin> = vec![];
            let mut tts: Vec<TagTypePlugin> = vec![];
            let mut mpes: Vec<MpePlugin> = vec![];
            for i in 0..npl {
                tags.push(TagPlugin {
                    base: PluginBase {
                        magic: 0x61637070,
                        ver: 2200,
                        typ: 0x74616748,
                        next: std::ptr::null_mut(),
                    },
                    sig: 0x74616730 + i * 0x100,
                    elem_count: 1,
                    n_supported: 2,
                    supported: {
                        let mut s = [0u32; 20];
                        s[0] = 0x63757276;
                        s[1] = 0x70617261;
                        s
                    },
                    decide: decide_type as *const std::ffi::c_void,
                });
                tts.push(TagTypePlugin {
                    base: PluginBase {
                        magic: 0x61637070,
                        ver: 2200,
                        typ: 0x74797048,
                        next: std::ptr::null_mut(),
                    },
                    sig: 0x74797030 + i * 0x100,
                    read: std::ptr::null(),
                    write: std::ptr::null(),
                    dup: std::ptr::null(),
                    free: std::ptr::null(),
                    ctx: std::ptr::null_mut(),
                    iccver: 0x04400000,
                });
                mpes.push(MpePlugin {
                    base: PluginBase {
                        magic: 0x61637070,
                        ver: 2200,
                        typ: 0x6D706548,
                        next: std::ptr::null_mut(),
                    },
                    sig: 0x6D706530 + i * 0x100,
                    n_in: 3,
                    n_out: 3,
                    eval: std::ptr::null(),
                    dup: std::ptr::null(),
                    free: std::ptr::null(),
                });
            }
            let mut ok = String::new();
            for p in &tags {
                ok += &format!(" t{}", c::cmsPluginTHR(ctx, p as *const _ as *mut _));
            }
            for p in &tts {
                ok += &format!(" tt{}", c::cmsPluginTHR(ctx, p as *const _ as *mut _));
            }
            for p in &mpes {
                ok += &format!(" m{}", c::cmsPluginTHR(ctx, p as *const _ as *mut _));
            }
            // dup the plugin-bearing context → DupTagList/
            //   DupTagTypeList list-walk internals
            let dctx = c::cmsDupContext(ctx, std::ptr::null_mut());
            eprintln!("{name}{ok} dup={}", !dctx.is_null());
            // also dup into a user-data context
            let ud = [0xABu8; 16];
            let dctx2 = c::cmsDupContext(ctx, ud.as_ptr() as *mut _);
            eprintln!("  dup+ud={}", !dctx2.is_null());
            if !dctx.is_null() {
                c::cmsDeleteContext(dctx);
            }
            if !dctx2.is_null() {
                c::cmsDeleteContext(dctx2);
            }
            c::cmsDeleteContext(ctx);
        }
        // chain: ctx -> dup -> dup-of-dup
        let c1 = c::cmsCreateContext(std::ptr::null_mut(), std::ptr::null_mut());
        let c2 = c::cmsDupContext(c1, std::ptr::null_mut());
        let c3 = c::cmsDupContext(c2, std::ptr::null_mut());
        eprintln!("chain c2={} c3={}", !c2.is_null(), !c3.is_null());
        if !c3.is_null() {
            c::cmsDeleteContext(c3);
        }
        if !c2.is_null() {
            c::cmsDeleteContext(c2);
        }
        c::cmsDeleteContext(c1);
        c::cmsCloseProfile(srgb);
        c::cmsFreeToneCurve(g);
    }
}

/// cmstypes residual — Type_Text_Description_Read +
///   _cmsReadWCharArray + ColorantTable/MPEmatrix/LUT8
///   read internals via crafted raw desc-type blobs.
#[test]
fn type_read32_arms() {
    fn be32(v: u32) -> [u8; 4] {
        v.to_be_bytes()
    }
    fn be16(v: u16) -> [u8; 2] {
        v.to_be_bytes()
    }
    unsafe {
        let srgb = c::cmsCreate_sRGBProfile();
        // descType blob = {sig 'desc'; reserved;
        //   u32 asciiLen; ascii+1; u32 uniCodeLangCode;
        //   u32 uniLen; u16*uniLen+1; u16 scriptCodeCode;
        //   u8 scriptLen; u8 script[67]}
        for (al, ul, sl, name) in [
            (0u32, 0u32, 0u8, "zeros"),
            (1, 0, 0, "a1"),
            (10, 0, 0, "a10"),
            (0, 10, 0, "u10"),
            (10, 10, 10, "all10"),
            (2, 200, 0, "u-oversize"),
            (10, 0x7FFFFFFF, 0, "u-huge"),
            (10, 10, 67, "s67"),
            (10, 10, 68, "s-over67"),
        ] {
            let mut blob = vec![];
            blob.extend_from_slice(b"desc\0\0\0\0");
            blob.extend_from_slice(&be32(al));
            let astr: Vec<u8> = (0..al).map(|i| b'A' + i as u8).collect();
            blob.extend_from_slice(&astr);
            blob.extend_from_slice(&be32(0x656E5553));
            blob.extend_from_slice(&be32(ul));
            for i in 0..ul.min(64) {
                blob.extend_from_slice(&be16(0x30 + (i as u16).min(0xFFF)));
            }
            blob.extend_from_slice(&be16(0x0002));
            blob.push(sl);
            for i in 0..67u8 {
                blob.push(b'0' + (i % 10));
            }
            // write raw blob into a tag + reopen+read
            let prof = c::cmsCreateProfilePlaceholder(std::ptr::null_mut());
            c::cmsSetDeviceClass(prof, 0x6D6E7472);
            c::cmsSetColorSpace(prof, 0x52474220);
            c::cmsSetPCS(prof, 0x58595A20);
            c::cmsSetProfileVersion(prof, 2.0);
            let w = c::cmsWriteRawTag(
                prof,
                0x64657363,
                blob.as_ptr() as *const _,
                blob.len() as u32,
            );
            let mut buf = vec![0u8; 1 << 20];
            let mut n = buf.len() as u32;
            let s = c::cmsSaveProfileToMem(prof, buf.as_mut_ptr() as *mut _, &mut n);
            let rp = if s != 0 {
                c::cmsOpenProfileFromMem(buf.as_ptr() as *const _, n)
            } else {
                std::ptr::null_mut()
            };
            if !rp.is_null() {
                let t = c::cmsReadTag(rp, 0x64657363);
                eprintln!(
                    "{name} w={w} s={s} \
                    t={}",
                    !t.is_null()
                );
                c::cmsCloseProfile(rp);
            } else {
                eprintln!("{name} w={w} s={s} rp=0");
            }
            c::cmsCloseProfile(prof);
        }
        // clrt (ColorantTableType) raw blobs
        for (ncol, name) in [(0u32, "0col"), (3, "3col"), (7, "7col"), (255, "255col")] {
            let mut blob = vec![];
            blob.extend_from_slice(b"clrt\0\0\0\0");
            blob.extend_from_slice(&be32(ncol));
            for i in 0..ncol.min(255) {
                let mut nm = [0u8; 32];
                nm[0] = b'C';
                nm[1] = (i as u8).wrapping_add(b'0');
                blob.extend_from_slice(&nm);
                blob.extend_from_slice(&be16(0x1000));
                blob.extend_from_slice(&be16(0x2000));
                blob.extend_from_slice(&be16(0x3000));
            }
            let prof = c::cmsCreateProfilePlaceholder(std::ptr::null_mut());
            c::cmsSetDeviceClass(prof, 0x6D6E7472);
            c::cmsSetColorSpace(prof, 0x52474220);
            c::cmsSetPCS(prof, 0x58595A20);
            c::cmsWriteRawTag(
                prof,
                0x636C7274,
                blob.as_ptr() as *const _,
                blob.len() as u32,
            );
            let mut buf = vec![0u8; 1 << 20];
            let mut n = buf.len() as u32;
            let s = c::cmsSaveProfileToMem(prof, buf.as_mut_ptr() as *mut _, &mut n);
            let rp = if s != 0 {
                c::cmsOpenProfileFromMem(buf.as_ptr() as *const _, n)
            } else {
                std::ptr::null_mut()
            };
            if !rp.is_null() {
                let t = c::cmsReadTag(rp, 0x636C7274);
                eprintln!("clrt {name} t={}", !t.is_null());
                c::cmsCloseProfile(rp);
            }
            c::cmsCloseProfile(prof);
        }
        c::cmsCloseProfile(srgb);
    }
}

/// cmstypes residual — Type_MPEmatrix_Read +
///   Type_LUT8_Read + Type_NamedColor_Read internals
///   via crafted mpAB matrix dims + mft1/ncl2 edges.
#[test]
fn type_read33_arms() {
    fn be32(v: u32) -> [u8; 4] {
        v.to_be_bytes()
    }
    fn be16(v: u16) -> [u8; 2] {
        v.to_be_bytes()
    }
    unsafe {
        let srgb = c::cmsCreate_sRGBProfile();
        // mpAB blob: {mpAB sig; 3B in; 3B out; u32 nelems;
        //   per elem: u32 sig u32 off u32 size}
        // matrix elem = {mat sig; u16 in u16 out;
        //   3x3 u32 f64s? actually s15f16 12 doubles}
        for (r, c2, name) in [
            (0u16, 0u16, "0x0"),
            (1, 1, "1x1"),
            (3, 3, "3x3"),
            (3, 4, "3x4"),
            (4, 3, "4x3"),
            (15, 15, "15x15"),
            (3, 0, "3x0"),
            (0, 3, "0x3"),
        ] {
            let mut blob = vec![];
            // matrix element content
            let mut melem = vec![];
            melem.extend_from_slice(b"matf");
            melem.extend_from_slice(&be16(r));
            melem.extend_from_slice(&be16(c2));
            let n_dbl = (r as usize).max(1) * (c2 as usize).max(1);
            for _ in 0..n_dbl {
                melem.extend_from_slice(&1.0f64.to_be_bytes());
            }
            melem.extend_from_slice(&be32(8 + 4 + n_dbl as u32 * 8)); // size
            blob.extend_from_slice(b"mpAB\0\0");
            blob.extend_from_slice(&[3, 0, 0, 3, 0, 0]);
            blob.extend_from_slice(&be32(1));
            blob.extend_from_slice(b"matf");
            blob.extend_from_slice(&be32(0x1C));
            blob.extend_from_slice(&be32(melem.len() as u32));
            blob.extend_from_slice(&melem);
            let prof = c::cmsCreateProfilePlaceholder(std::ptr::null_mut());
            c::cmsSetDeviceClass(prof, 0x6D6E7472);
            c::cmsSetColorSpace(prof, 0x52474220);
            c::cmsSetPCS(prof, 0x58595A20);
            c::cmsSetProfileVersion(prof, 4.4);
            c::cmsWriteRawTag(
                prof,
                0x41324230,
                blob.as_ptr() as *const _,
                blob.len() as u32,
            );
            let mut buf = vec![0u8; 1 << 20];
            let mut n = buf.len() as u32;
            let s = c::cmsSaveProfileToMem(prof, buf.as_mut_ptr() as *mut _, &mut n);
            let rp = if s != 0 {
                c::cmsOpenProfileFromMem(buf.as_ptr() as *const _, n)
            } else {
                std::ptr::null_mut()
            };
            if !rp.is_null() {
                let t = c::cmsReadTag(rp, 0x41324230);
                eprintln!("mpe-mat {name} t={}", !t.is_null());
                c::cmsCloseProfile(rp);
            }
            c::cmsCloseProfile(prof);
        }
        // mft1 LUT8 edge grid sizes + padding
        for (grid, name) in [
            (2u8, "g2"),
            (3, "g3"),
            (16, "g16"),
            (255, "g255"),
            (0, "g0"),
        ] {
            let mut blob = vec![];
            blob.extend_from_slice(b"mft1");
            blob.extend_from_slice(&[0; 3]);
            blob.push(3); // in ch
            blob.push(3); // out ch
            blob.push(grid);
            blob.push(0);
            for _ in 0..9 {
                blob.extend_from_slice(&be16(0x1000));
            }
            let nc = grid as usize;
            let ntab = if grid == 0 { 0 } else { nc * nc * nc * 3 };
            for i in 0..ntab.min(4096) {
                blob.push(i as u8);
            }
            // 3 x 256 u8 input tables + clut + out tables
            blob.extend(std::iter::repeat_n(0, 3 * 256));
            for i in 0..ntab.min(4096) {
                blob.push(i as u8);
            }
            blob.extend(std::iter::repeat_n(255, 3 * 256));
            let prof = c::cmsCreateProfilePlaceholder(std::ptr::null_mut());
            c::cmsSetDeviceClass(prof, 0x6D6E7472);
            c::cmsSetColorSpace(prof, 0x52474220);
            c::cmsSetPCS(prof, 0x58595A20);
            c::cmsSetProfileVersion(prof, 2.0);
            c::cmsWriteRawTag(
                prof,
                0x41324230,
                blob.as_ptr() as *const _,
                blob.len() as u32,
            );
            let mut buf = vec![0u8; 1 << 20];
            let mut n = buf.len() as u32;
            let s = c::cmsSaveProfileToMem(prof, buf.as_mut_ptr() as *mut _, &mut n);
            let rp = if s != 0 {
                c::cmsOpenProfileFromMem(buf.as_ptr() as *const _, n)
            } else {
                std::ptr::null_mut()
            };
            if !rp.is_null() {
                let t = c::cmsReadTag(rp, 0x41324230);
                eprintln!("mft1 {name} t={}", !t.is_null());
                c::cmsCloseProfile(rp);
            }
            c::cmsCloseProfile(prof);
        }
        // ncl2 edge colorant counts
        for (nc, name) in [(1u16, "1c"), (4, "4c"), (15, "15c"), (0, "0c")] {
            let mut blob = vec![];
            blob.extend_from_slice(b"ncl2\0\0\0\0");
            blob.extend_from_slice(&be16(0));
            blob.extend_from_slice(&be16(nc));
            blob.extend_from_slice(&be32(0));
            for i in 0..nc {
                let mut nm = [0u8; 32];
                nm[0] = b'N';
                nm[1] = i as u8 + b'0';
                blob.extend_from_slice(&nm);
                blob.extend_from_slice(&be16(0x1000));
                blob.extend_from_slice(&be16(0x2000));
                blob.extend_from_slice(&be16(0x3000));
            }
            let prof = c::cmsCreateProfilePlaceholder(std::ptr::null_mut());
            c::cmsSetDeviceClass(prof, 0x6D6E7472);
            c::cmsSetColorSpace(prof, 0x52474220);
            c::cmsSetPCS(prof, 0x58595A20);
            c::cmsWriteRawTag(
                prof,
                0x6E636C32,
                blob.as_ptr() as *const _,
                blob.len() as u32,
            );
            let mut buf = vec![0u8; 1 << 20];
            let mut n = buf.len() as u32;
            let s = c::cmsSaveProfileToMem(prof, buf.as_mut_ptr() as *mut _, &mut n);
            let rp = if s != 0 {
                c::cmsOpenProfileFromMem(buf.as_ptr() as *const _, n)
            } else {
                std::ptr::null_mut()
            };
            if !rp.is_null() {
                let t = c::cmsReadTag(rp, 0x6E636C32);
                eprintln!("ncl2 {name} t={}", !t.is_null());
                c::cmsCloseProfile(rp);
            }
            c::cmsCloseProfile(prof);
        }
        c::cmsCloseProfile(srgb);
    }
}

/// cmstypes residual — WriteSetOfCurves/WriteMatrix MPE
///   internals via cvst/matf element writes of edge
///   channel/dim counts.
#[test]
fn type_write38_arms() {
    unsafe {
        let srgb = c::cmsCreate_sRGBProfile();
        let g = c::cmsBuildGamma(std::ptr::null_mut(), 2.2);
        // cvst curve-sets on 1/3/4/15 channels + matf
        //   matrices 1x1/2x2/4x4/15x15
        for nch in [1u32, 3, 4, 15] {
            for ver in [2.0f64, 4.4] {
                let prof = c::cmsCreateProfilePlaceholder(std::ptr::null_mut());
                c::cmsSetDeviceClass(prof, 0x6D6E7472);
                c::cmsSetColorSpace(prof, 0x52474220);
                c::cmsSetPCS(prof, 0x58595A20);
                c::cmsSetProfileVersion(prof, ver);
                let p = c::cmsPipelineAlloc(std::ptr::null_mut(), nch, nch);
                let trcs = vec![g; nch as usize];
                c::cmsPipelineInsertStage(
                    p,
                    0,
                    c::cmsStageAllocToneCurves(std::ptr::null_mut(), nch, trcs.as_ptr() as *mut _),
                );
                c::cmsWriteTag(prof, 0x41324230, p as *const _);
                let mut buf = vec![0u8; 1 << 20];
                let mut n = buf.len() as u32;
                let s = c::cmsSaveProfileToMem(prof, buf.as_mut_ptr() as *mut _, &mut n);
                eprintln!("cvst {nch}ch v{ver} s={s}");
                c::cmsCloseProfile(prof);
                c::cmsPipelineFree(p);
            }
        }
        // matf matrices edge dims in mAB
        for (rin, rout, name) in [
            (1u32, 1u32, "1x1"),
            (2, 2, "2x2"),
            (3, 3, "3x3"),
            (4, 4, "4x4"),
            (15, 15, "15x15"),
        ] {
            let prof = c::cmsCreateProfilePlaceholder(std::ptr::null_mut());
            c::cmsSetDeviceClass(prof, 0x6D6E7472);
            c::cmsSetColorSpace(prof, 0x52474220);
            c::cmsSetPCS(prof, 0x58595A20);
            c::cmsSetProfileVersion(prof, 4.4);
            let p = c::cmsPipelineAlloc(std::ptr::null_mut(), rin, rout);
            let mat = vec![0.1f64; (rin * rout) as usize];
            c::cmsPipelineInsertStage(
                p,
                0,
                c::cmsStageAllocMatrix(
                    std::ptr::null_mut(),
                    rin,
                    rout,
                    mat.as_ptr(),
                    std::ptr::null(),
                ),
            );
            c::cmsWriteTag(prof, 0x41324230, p as *const _);
            let mut buf = vec![0u8; 1 << 20];
            let mut n = buf.len() as u32;
            let s = c::cmsSaveProfileToMem(prof, buf.as_mut_ptr() as *mut _, &mut n);
            eprintln!("matf {name} s={s}");
            // mixed: matf + cvst + clut in one pipeline
            let p2 = c::cmsPipelineAlloc(std::ptr::null_mut(), rin, rout);
            let trcs2 = vec![g; rout as usize];
            let dims2 = [2u32; 15];
            let npt = (2u64.pow(rin) * rout as u64) as usize;
            let grid = vec![0.5f32; npt];
            c::cmsPipelineInsertStage(
                p2,
                0,
                c::cmsStageAllocMatrix(
                    std::ptr::null_mut(),
                    rin,
                    rout,
                    mat.as_ptr(),
                    std::ptr::null(),
                ),
            );
            c::cmsPipelineInsertStage(
                p2,
                1,
                c::cmsStageAllocToneCurves(std::ptr::null_mut(), rout, trcs2.as_ptr() as *mut _),
            );
            c::cmsPipelineInsertStage(
                p2,
                2,
                c::cmsStageAllocCLutFloatGranular(
                    std::ptr::null_mut(),
                    dims2.as_ptr(),
                    rin.min(15),
                    rout,
                    grid.as_ptr(),
                ),
            );
            c::cmsWriteTag(prof, 0x42324130, p2 as *const _);
            let mut n2 = buf.len() as u32;
            let s2 = c::cmsSaveProfileToMem(prof, buf.as_mut_ptr() as *mut _, &mut n2);
            eprintln!("  mixed {name} s={s2}");
            c::cmsCloseProfile(prof);
            c::cmsPipelineFree(p);
            c::cmsPipelineFree(p2);
        }
        c::cmsCloseProfile(srgb);
        c::cmsFreeToneCurve(g);
    }
}

/// cmstypes residual — Type_Screening_Read +
///   ReadOneWChar internals via scrn-type raw blobs +
///   desc unicode edge cases.
#[test]
fn type_read34_arms() {
    fn be32(v: u32) -> [u8; 4] {
        v.to_be_bytes()
    }
    fn be16(v: u16) -> [u8; 2] {
        v.to_be_bytes()
    }
    unsafe {
        // scrnType = {sig 'scrn'; reserved; u32 channels;
        //   per ch: f64 freq f64 angle u32 shape}
        for (nch, name) in [
            (0u32, "0ch"),
            (1, "1ch"),
            (4, "4ch"),
            (7, "7ch"),
            (15, "15ch"),
            (16, "16ch"),
        ] {
            let mut blob = vec![];
            blob.extend_from_slice(b"scrn\0\0\0\0");
            blob.extend_from_slice(&be32(nch));
            for i in 0..nch {
                blob.extend_from_slice(&(10.0 + i as f64).to_be_bytes());
                blob.extend_from_slice(&(i as f64 * 15.0).to_be_bytes());
                blob.extend_from_slice(&be32(i % 4));
            }
            let prof = c::cmsCreateProfilePlaceholder(std::ptr::null_mut());
            c::cmsSetDeviceClass(prof, 0x6D6E7472);
            c::cmsSetColorSpace(prof, 0x52474220);
            c::cmsSetPCS(prof, 0x58595A20);
            c::cmsWriteRawTag(
                prof,
                0x7363726E,
                blob.as_ptr() as *const _,
                blob.len() as u32,
            );
            let mut buf = vec![0u8; 1 << 20];
            let mut n = buf.len() as u32;
            let s = c::cmsSaveProfileToMem(prof, buf.as_mut_ptr() as *mut _, &mut n);
            let rp = if s != 0 {
                c::cmsOpenProfileFromMem(buf.as_ptr() as *const _, n)
            } else {
                std::ptr::null_mut()
            };
            if !rp.is_null() {
                let t = c::cmsReadTag(rp, 0x7363726E);
                eprintln!("scrn {name} t={}", !t.is_null());
                c::cmsCloseProfile(rp);
            } else {
                eprintln!("scrn {name} rp=0");
            }
            c::cmsCloseProfile(prof);
        }
        // desc unicode edge cases — surrogate pairs,
        //   unpaired surrogates, non-ASCII
        for (vals, name) in [
            (vec![0x0041u16, 0x0042], "ascii"),
            (vec![0x00E9u16, 0x20AC], "latin"),
            (vec![0xD800u16, 0xDC00], "sur-pair"),
            (vec![0xD800u16], "hi-only"),
            (vec![0xDC00u16], "lo-only"),
            (vec![0xDBFFu16, 0xDFFF], "hi-max"),
            (vec![0xD800u16, 0x0041], "hi+ascii"),
            (vec![0x0041u16, 0xDC00], "ascii+lo"),
            (vec![0xFFFDu16], "repl"),
            (vec![0xFFFFu16], "xffff"),
            (vec![0x0000u16, 0x0041], "nul-mid"),
            (vec![0x0080u16, 0x07FF], "2b-range"),
            (vec![0x0800u16, 0xD7FF], "3b-range"),
            (vec![0xE000u16, 0xFFFE], "pvt"),
        ] {
            let mut blob = vec![];
            blob.extend_from_slice(b"desc\0\0\0\0");
            blob.extend_from_slice(&be32(2));
            blob.extend_from_slice(b"X\0");
            blob.extend_from_slice(&be32(0x656E5553));
            blob.extend_from_slice(&be32(vals.len() as u32));
            for &v in &vals {
                blob.extend_from_slice(&be16(v));
            }
            blob.extend_from_slice(&be16(0x0002));
            blob.push(0);
            blob.extend(std::iter::repeat_n(0, 67));
            let prof = c::cmsCreateProfilePlaceholder(std::ptr::null_mut());
            c::cmsSetDeviceClass(prof, 0x6D6E7472);
            c::cmsSetColorSpace(prof, 0x52474220);
            c::cmsSetPCS(prof, 0x58595A20);
            c::cmsSetProfileVersion(prof, 2.0);
            c::cmsWriteRawTag(
                prof,
                0x64657363,
                blob.as_ptr() as *const _,
                blob.len() as u32,
            );
            let mut buf = vec![0u8; 1 << 20];
            let mut n = buf.len() as u32;
            let s = c::cmsSaveProfileToMem(prof, buf.as_mut_ptr() as *mut _, &mut n);
            let rp = if s != 0 {
                c::cmsOpenProfileFromMem(buf.as_ptr() as *const _, n)
            } else {
                std::ptr::null_mut()
            };
            if !rp.is_null() {
                let t = c::cmsReadTag(rp, 0x64657363);
                eprintln!("desc {name} t={}", !t.is_null());
                c::cmsCloseProfile(rp);
            }
            c::cmsCloseProfile(prof);
        }
    }
}

/// cmstypes residual — Type_Text_Description_Read error
///   paths via truncated unicode/ascii data at EOF.
#[test]
fn type_read35_arms() {
    fn be32(v: u32) -> [u8; 4] {
        v.to_be_bytes()
    }
    fn be16(v: u16) -> [u8; 2] {
        v.to_be_bytes()
    }
    unsafe {
        // desc blob truncated mid-unicode →
        //   _cmsReadWCharArray FALSE → error+free path
        for (al, ul_decl, ul_write, name) in [
            (2u32, 100u32, 0usize, "trunc-u"),
            (2, 10, 3, "partial-u"),
            (100, 0, 0, "trunc-a"),
            (0x7FFFFFFF, 0, 0, "huge-a"),
            (2, 0x7FFFFFFF, 0, "huge-u"),
        ] {
            let mut blob = vec![];
            blob.extend_from_slice(b"desc\0\0\0\0");
            blob.extend_from_slice(&be32(al));
            for i in 0..al.min(4) {
                blob.push(b'A' + i as u8);
            }
            blob.extend_from_slice(&be32(0x656E5553));
            blob.extend_from_slice(&be32(ul_decl));
            for i in 0..ul_write {
                blob.extend_from_slice(&be16(0x30 + (i as u16).min(0xFF)));
            }
            blob.extend_from_slice(&be16(0x0002));
            blob.push(0);
            blob.extend(std::iter::repeat_n(0, 67));
            // write desc as the LAST tag — append a bogus
            //   high-sig tag first so desc sits at EOF
            let prof = c::cmsCreateProfilePlaceholder(std::ptr::null_mut());
            c::cmsSetDeviceClass(prof, 0x6D6E7472);
            c::cmsSetColorSpace(prof, 0x52474220);
            c::cmsSetPCS(prof, 0x58595A20);
            c::cmsSetProfileVersion(prof, 2.0);
            c::cmsWriteRawTag(prof, 0xAAAAAAAA, b"x".as_ptr() as *const _, 1);
            c::cmsWriteRawTag(
                prof,
                0x64657363,
                blob.as_ptr() as *const _,
                blob.len() as u32,
            );
            let mut buf = vec![0u8; 1 << 20];
            let mut n = buf.len() as u32;
            let s = c::cmsSaveProfileToMem(prof, buf.as_mut_ptr() as *mut _, &mut n);
            let rp = if s != 0 {
                c::cmsOpenProfileFromMem(buf.as_ptr() as *const _, n)
            } else {
                std::ptr::null_mut()
            };
            if !rp.is_null() {
                let t = c::cmsReadTag(rp, 0x64657363);
                eprintln!("{name} s={s} t={}", !t.is_null());
                c::cmsCloseProfile(rp);
            } else {
                eprintln!("{name} s={s} rp=0");
            }
            c::cmsCloseProfile(prof);
        }
        // tag size smaller than declared fields — craft
        //   a profile where desc's declared tag-size is
        //   shorter than its internal counts claim:
        //   build valid profile, then corrupt the size
        let mut blob = vec![];
        blob.extend_from_slice(b"desc\0\0\0\0");
        blob.extend_from_slice(&be32(4));
        blob.extend_from_slice(b"TXT\0");
        blob.extend_from_slice(&be32(0x656E5553));
        blob.extend_from_slice(&be32(3));
        for _ in 0..3 {
            blob.extend_from_slice(&be16(0x41));
        }
        blob.extend_from_slice(&be16(0x0002));
        blob.push(0);
        blob.extend(std::iter::repeat_n(0, 67));
        let prof = c::cmsCreateProfilePlaceholder(std::ptr::null_mut());
        c::cmsSetDeviceClass(prof, 0x6D6E7472);
        c::cmsSetColorSpace(prof, 0x52474220);
        c::cmsSetPCS(prof, 0x58595A20);
        c::cmsSetProfileVersion(prof, 2.0);
        c::cmsWriteRawTag(
            prof,
            0x64657363,
            blob.as_ptr() as *const _,
            blob.len() as u32,
        );
        let mut buf = vec![0u8; 1 << 20];
        let mut n = buf.len() as u32;
        c::cmsSaveProfileToMem(prof, buf.as_mut_ptr() as *mut _, &mut n);
        // corrupt: shrink the desc tag's declared size —
        //   tag table starts at offset 128: u32 count,
        //   then per-tag {sig,off,size}
        let cnt = u32::from_be_bytes(buf[128..132].try_into().unwrap());
        for i in 0..cnt as usize {
            let e = 132 + i * 12;
            let sig = u32::from_be_bytes(buf[e..e + 4].try_into().unwrap());
            if sig == 0x64657363 {
                buf[e + 8..e + 12].copy_from_slice(&be32(20)); // tiny size
            }
        }
        let rp = c::cmsOpenProfileFromMem(buf.as_ptr() as *const _, n);
        if !rp.is_null() {
            let t = c::cmsReadTag(rp, 0x64657363);
            eprintln!("shrunk-size t={}", !t.is_null());
            c::cmsCloseProfile(rp);
        }
        c::cmsCloseProfile(prof);
    }
}

