/// cmstypes residual — LUTB2A/LUTA2B read internals
///   via mft2 malformed: truncations at each field +
///   bad channel/grid counts.
#[test]
fn type_read64_arms() {
    unsafe {
        // mft2: sig+res+inch+outch+grid+u8/u16+pad +
        //   input-table + clut + output-table
        for (inch, outch, grid, prec, name) in [
            (3u8, 3u8, 2u8, 0u8, "33g2"),
            (1, 1, 2, 0, "11g2"),
            (4, 4, 2, 0, "44g2"),
            (3, 3, 0, 0, "33g0"),
            (0, 3, 2, 0, "0ch"),
            (3, 0, 2, 0, "0ch-out"),
            (16, 16, 2, 0, "16ch"),
            (3, 3, 255, 0, "g255"),
        ] {
            let mut blob = vec![0x6D, 0x66, 0x74, 0x32, 0, 0, 0, 0];
            blob.extend_from_slice(&inch.to_be_bytes());
            blob.extend_from_slice(&outch.to_be_bytes());
            blob.extend_from_slice(&grid.to_be_bytes());
            blob.extend_from_slice(&prec.to_be_bytes());
            for i in 0..9 {
                let v = if i % 4 == 0 { 1.0f64 } else { 0.0 };
                blob.extend_from_slice(&v.to_be_bytes());
            }
            let npts = (grid as usize).pow(inch as u32).max(1) * 3;
            // input table 256 entries
            for _ in 0..256 {
                blob.extend_from_slice(&0x4000u16.to_be_bytes());
            }
            // clut
            for _ in 0..npts {
                blob.extend_from_slice(&0x4000u16.to_be_bytes());
            }
            // output table
            for _ in 0..256 {
                blob.extend_from_slice(&0x4000u16.to_be_bytes());
            }
            let p = c::cmsCreateProfilePlaceholder(std::ptr::null_mut());
            c::cmsSetDeviceClass(p, 0x6D6E7472);
            c::cmsSetColorSpace(p, 0x52474220);
            c::cmsSetPCS(p, 0x4C616220);
            c::cmsSetProfileVersion(p, 2.4);
            c::cmsWriteRawTag(p, 0x41324230, blob.as_ptr() as *const _, blob.len() as u32);
            let mut buf = [0u8; 1 << 19];
            let mut nn = buf.len() as u32;
            let sv = c::cmsSaveProfileToMem(p, buf.as_mut_ptr() as *mut _, &mut nn);
            let pr = if sv != 0 {
                c::cmsOpenProfileFromMem(buf.as_ptr() as *const _, nn)
            } else {
                std::ptr::null_mut()
            };
            let rd = if !pr.is_null() {
                c::cmsReadTag(pr, 0x41324230)
            } else {
                std::ptr::null_mut()
            };
            eprintln!("mft2 {name} rd={}", !rd.is_null());
            if !pr.is_null() {
                c::cmsCloseProfile(pr);
            }
            c::cmsCloseProfile(p);
        }
        // mft2 truncation sweep at each section
        for cut in [0usize, 8, 52, 56, 256, 512, 1024, 2048] {
            let mut blob = vec![0x6D, 0x66, 0x74, 0x32, 0, 0, 0, 0, 3, 3, 2, 0];
            for i in 0..9 {
                let v = if i % 4 == 0 { 1.0f64 } else { 0.0 };
                blob.extend_from_slice(&v.to_be_bytes());
            }
            for _ in 0..256 {
                blob.extend_from_slice(&0x4000u16.to_be_bytes());
            }
            for _ in 0..27 {
                blob.extend_from_slice(&0x4000u16.to_be_bytes());
            }
            for _ in 0..256 {
                blob.extend_from_slice(&0x4000u16.to_be_bytes());
            }
            let blob = &blob[..cut.min(blob.len())];
            let p = c::cmsCreateProfilePlaceholder(std::ptr::null_mut());
            c::cmsSetDeviceClass(p, 0x6D6E7472);
            c::cmsSetColorSpace(p, 0x52474220);
            c::cmsSetPCS(p, 0x4C616220);
            c::cmsSetProfileVersion(p, 2.4);
            c::cmsWriteRawTag(p, 0x41324230, blob.as_ptr() as *const _, blob.len() as u32);
            let mut buf = [0u8; 1 << 19];
            let mut nn = buf.len() as u32;
            let sv = c::cmsSaveProfileToMem(p, buf.as_mut_ptr() as *mut _, &mut nn);
            let pr = if sv != 0 {
                c::cmsOpenProfileFromMem(buf.as_ptr() as *const _, nn)
            } else {
                std::ptr::null_mut()
            };
            let rd = if !pr.is_null() {
                c::cmsReadTag(pr, 0x41324230)
            } else {
                std::ptr::null_mut()
            };
            eprintln!("mft2-cut{cut} rd={}", !rd.is_null());
            if !pr.is_null() {
                c::cmsCloseProfile(pr);
            }
            c::cmsCloseProfile(p);
        }
    }
}

