/// cmstypes residual — ResponseCurve/CrdInfo read
///   internals via resp/crdi blob variants.
#[test]
fn type_read67_arms() {
    unsafe {
        // 'resp': counts + per-channel curve offsets
        for (nc, name) in [
            (3u16, "3ch"),
            (1, "1ch"),
            (4, "4ch"),
            (0, "0ch"),
            (16, "16ch"),
        ] {
            let mut blob = vec![0x72, 0x65, 0x73, 0x70, 0, 0, 0, 0];
            blob.extend_from_slice(&nc.to_be_bytes());
            blob.extend_from_slice(&0u16.to_be_bytes());
            for i in 0..nc {
                blob.extend_from_slice(&(i as u32 * 0x10).to_be_bytes());
                blob.extend_from_slice(&(0x80u16).to_be_bytes());
            }
            // meas + response units
            for _ in 0..nc {
                blob.extend_from_slice(&0x70727472u32.to_be_bytes());
                blob.extend_from_slice(&0x10u32.to_be_bytes());
            }
            for _ in 0..nc {
                for _ in 0..256 {
                    blob.extend_from_slice(&0x8000u16.to_be_bytes());
                }
            }
            let p = c::cmsCreateProfilePlaceholder(std::ptr::null_mut());
            c::cmsSetDeviceClass(p, 0x6D6E7472);
            c::cmsSetColorSpace(p, 0x52474220);
            c::cmsSetPCS(p, 0x58595A20);
            c::cmsSetProfileVersion(p, 2.4);
            c::cmsWriteRawTag(p, 0x72657370, blob.as_ptr() as *const _, blob.len() as u32);
            let mut buf = [0u8; 1 << 19];
            let mut nn = buf.len() as u32;
            let sv = c::cmsSaveProfileToMem(p, buf.as_mut_ptr() as *mut _, &mut nn);
            let pr = if sv != 0 {
                c::cmsOpenProfileFromMem(buf.as_ptr() as *const _, nn)
            } else {
                std::ptr::null_mut()
            };
            let rd = if !pr.is_null() {
                c::cmsReadTag(pr, 0x72657370)
            } else {
                std::ptr::null_mut()
            };
            eprintln!("resp {name} rd={}", !rd.is_null());
            if !pr.is_null() {
                c::cmsCloseProfile(pr);
            }
            c::cmsCloseProfile(p);
        }
        // 'crdi': product + render + desc + CRD sizes
        for (sz, name) in [(4u32, "sz4"), (16, "sz16"), (64, "sz64"), (0, "sz0")] {
            let mut blob = vec![0x63, 0x72, 0x64, 0x69, 0, 0, 0, 0];
            // product count + u16 product name
            blob.extend_from_slice(&4u32.to_be_bytes());
            blob.extend_from_slice(b"prod");
            while blob.len() % 4 != 0 {
                blob.push(0);
            }
            // render intent u32
            blob.extend_from_slice(&0u32.to_be_bytes());
            // desc count + utf8
            blob.extend_from_slice(&4u32.to_be_bytes());
            blob.extend_from_slice(b"desc");
            while blob.len() % 4 != 0 {
                blob.push(0);
            }
            // CRD size u32 + CRD data
            blob.extend_from_slice(&sz.to_be_bytes());
            blob.extend_from_slice(&vec![0x80u8; sz as usize]);
            let p = c::cmsCreateProfilePlaceholder(std::ptr::null_mut());
            c::cmsSetDeviceClass(p, 0x6D6E7472);
            c::cmsSetColorSpace(p, 0x52474220);
            c::cmsSetPCS(p, 0x58595A20);
            c::cmsSetProfileVersion(p, 2.4);
            c::cmsWriteRawTag(p, 0x63726469, blob.as_ptr() as *const _, blob.len() as u32);
            let mut buf = [0u8; 1 << 18];
            let mut nn = buf.len() as u32;
            let sv = c::cmsSaveProfileToMem(p, buf.as_mut_ptr() as *mut _, &mut nn);
            let pr = if sv != 0 {
                c::cmsOpenProfileFromMem(buf.as_ptr() as *const _, nn)
            } else {
                std::ptr::null_mut()
            };
            let rd = if !pr.is_null() {
                c::cmsReadTag(pr, 0x63726469)
            } else {
                std::ptr::null_mut()
            };
            eprintln!("crdi {name} rd={}", !rd.is_null());
            if !pr.is_null() {
                c::cmsCloseProfile(pr);
            }
            c::cmsCloseProfile(p);
        }
    }
}

