/// cmstypes residual — LUTB2A write internals via
///   mBA pipelines on output-class + prtr profiles.
#[test]
fn type_write58_arms() {
    unsafe {
        let g = c::cmsBuildGamma(std::ptr::null_mut(), 1.0);
        for (inch, outch, name) in [
            (3u32, 3u32, "33"),
            (4, 4, "44"),
            (3, 1, "31"),
            (1, 3, "13"),
            (2, 2, "22"),
        ] {
            let nch = inch.max(outch);
            let tcs: Vec<*mut c::ToneCurve> = vec![g; nch as usize];
            let pipe = c::cmsPipelineAlloc(std::ptr::null_mut(), inch, outch);
            c::cmsPipelineInsertStage(
                pipe,
                -1,
                c::cmsStageAllocToneCurves(std::ptr::null_mut(), inch, tcs.as_ptr() as *mut _),
            );
            if inch == outch {
                let n = inch as usize;
                let m: Vec<f64> = (0..n * n)
                    .map(|i| if i % (n + 1) == 0 { 1.0 } else { 0.0 })
                    .collect();
                c::cmsPipelineInsertStage(
                    pipe,
                    -1,
                    c::cmsStageAllocMatrix(
                        std::ptr::null_mut(),
                        inch,
                        outch,
                        m.as_ptr(),
                        std::ptr::null(),
                    ),
                );
            }
            let dims = [2u32; 15];
            let npts = 2usize.pow(inch.min(8));
            let grid = vec![0x8000u16; npts * outch as usize];
            c::cmsPipelineInsertStage(
                pipe,
                -1,
                c::cmsStageAllocCLut16bitGranular(
                    std::ptr::null_mut(),
                    dims.as_ptr(),
                    inch,
                    outch,
                    grid.as_ptr(),
                ),
            );
            for cls in [0x70727472u32, 0x6C696E6B, 0x6D6E7472] {
                let p = c::cmsCreateProfilePlaceholder(std::ptr::null_mut());
                c::cmsSetDeviceClass(p, cls);
                c::cmsSetColorSpace(p, 0x434D594B);
                c::cmsSetPCS(p, 0x4C616220);
                c::cmsSetProfileVersion(p, 4.4);
                c::cmsWriteTag(p, 0x42324130, pipe as *const _);
                let mut buf = [0u8; 1 << 18];
                let mut nn = buf.len() as u32;
                let sv = c::cmsSaveProfileToMem(p, buf.as_mut_ptr() as *mut _, &mut nn);
                if sv != 0 {
                    eprintln!("{name} {cls:#x} sv n={nn}");
                }
                c::cmsCloseProfile(p);
            }
            c::cmsPipelineFree(pipe);
        }
        c::cmsFreeToneCurve(g);
    }
}

