/// cmstypes residual — mAB read internals via element-
///   order variants (B-curves first, matrix mid, etc).
#[test]
fn type_read73_arms() {
    unsafe {
        // mAB with 1-5 stage elements in various
        //   arrangements
        for (shape, name) in [
            (0u8, "b-only"),
            (1, "b+a"),
            (2, "b+mat"),
            (3, "b+mat+a"),
            (4, "a-only"),
            (5, "mat-only"),
            (6, "b+clut"),
            (7, "b+mat+clut+a"),
        ] {
            let mut blob = vec![0x6D, 0x41, 0x42, 0x20, 0, 0, 0, 0];
            blob.extend_from_slice(&3u8.to_be_bytes());
            blob.extend_from_slice(&3u8.to_be_bytes());
            blob.extend_from_slice(&[0u8; 2]);
            let curv_block = || {
                let mut b = vec![0x63u8, 0x75, 0x72, 0x76, 0, 0, 0, 0];
                b.extend_from_slice(&2u32.to_be_bytes());
                b.extend_from_slice(&0x4000u16.to_be_bytes());
                b.extend_from_slice(&0x8000u16.to_be_bytes());
                b
            };
            let mat_block = || {
                let mut b = vec![0x6Du8, 0x61, 0x74, 0x66, 0, 0, 0, 0];
                for i in 0..9 {
                    let v = if i % 4 == 0 { 1.0f64 } else { 0.0 };
                    b.extend_from_slice(&v.to_be_bytes());
                }
                b
            };
            let clut_block = || {
                let mut b = vec![2u8; 16];
                b.extend_from_slice(&[1u8, 0, 0, 0]);
                b.extend_from_slice(&[0x80u8; 8 * 3]);
                b
            };
            let mut offs = [0u32; 5];
            let mut pos = 48u32;
            if (shape == 0 || shape >= 1 && shape != 4 && shape != 5) && (shape <= 3 || shape >= 6)
            {
                // B curves at offset 48
                offs[0] = pos;
                for _ in 0..3 {
                    pos += curv_block().len() as u32;
                }
            }
            if (2..=3).contains(&shape) || shape == 7 {
                offs[1] = pos;
                pos += mat_block().len() as u32;
            }
            if shape >= 6 && shape != 7 || shape == 7 {
                offs[3] = pos;
                pos += clut_block().len() as u32;
            }
            if shape >= 1 && shape != 4 && shape != 5 {
                offs[4] = pos;
            }
            for o in offs {
                blob.extend_from_slice(&o.to_be_bytes());
            }
            // append element bodies in order
            if offs[0] != 0 {
                for _ in 0..3 {
                    blob.extend_from_slice(&curv_block());
                }
            }
            if offs[1] != 0 {
                blob.extend_from_slice(&mat_block());
            }
            if offs[3] != 0 {
                blob.extend_from_slice(&clut_block());
            }
            if offs[4] != 0 {
                for _ in 0..3 {
                    blob.extend_from_slice(&curv_block());
                }
            }
            let p = c::cmsCreateProfilePlaceholder(std::ptr::null_mut());
            c::cmsSetDeviceClass(p, 0x6D6E7472);
            c::cmsSetColorSpace(p, 0x52474220);
            c::cmsSetPCS(p, 0x4C616220);
            c::cmsSetProfileVersion(p, 4.4);
            c::cmsWriteRawTag(p, 0x41324230, blob.as_ptr() as *const _, blob.len() as u32);
            let mut buf = [0u8; 1 << 18];
            let mut nn = buf.len() as u32;
            let sv = c::cmsSaveProfileToMem(p, buf.as_mut_ptr() as *mut _, &mut nn);
            let pr = if sv != 0 {
                c::cmsOpenProfileFromMem(buf.as_ptr() as *const _, nn)
            } else {
                std::ptr::null_mut()
            };
            let rd = if !pr.is_null() {
                c::cmsReadTag(pr, 0x41324230)
            } else {
                std::ptr::null_mut()
            };
            eprintln!("mab {name} rd={}", !rd.is_null());
            if !pr.is_null() {
                c::cmsCloseProfile(pr);
            }
            c::cmsCloseProfile(p);
        }
    }
}

/// cmstypes residual — mBA read internals via element-
///   order variants on output class.
#[test]
fn type_read74_arms() {
    unsafe {
        // mBA on prtr: B-curves + matrix + clut + A
        for (shape, name) in [
            (0u8, "a-only"),
            (1, "a+b"),
            (2, "a+mat"),
            (3, "a+mat+b"),
            (4, "a+clut"),
            (5, "a+mat+clut+b"),
            (6, "b-only"),
            (7, "mat-only"),
        ] {
            let mut blob = vec![0x6D, 0x42, 0x41, 0x20, 0, 0, 0, 0];
            blob.extend_from_slice(&3u8.to_be_bytes());
            blob.extend_from_slice(&3u8.to_be_bytes());
            blob.extend_from_slice(&[0u8; 2]);
            let mut offs = [0u32; 5];
            let mut pos = 48u32;
            if shape == 0 || shape == 6 {
                offs[4] = pos; // A curves only
            } else {
                // B curves
                offs[0] = pos;
                for _ in 0..3 {
                    pos += 14;
                }
            }
            if shape >= 2 && shape != 4 && shape != 6 && shape != 7 {
                offs[1] = pos;
                pos += 72;
            }
            if shape >= 4 && shape != 7 {
                offs[3] = pos;
                pos += 36;
            }
            if shape >= 1 && shape != 6 && shape != 7 {
                offs[4] = pos;
            }
            for o in offs {
                blob.extend_from_slice(&o.to_be_bytes());
            }
            // B-curves bodies
            if offs[0] != 0 {
                for _ in 0..3 {
                    blob.extend_from_slice(&[0x63u8, 0x75, 0x72, 0x76, 0, 0, 0, 0]);
                    blob.extend_from_slice(&2u32.to_be_bytes());
                    blob.extend_from_slice(&0x4000u16.to_be_bytes());
                    blob.extend_from_slice(&0x8000u16.to_be_bytes());
                }
            }
            if offs[1] != 0 {
                blob.extend_from_slice(&[0x6Du8, 0x61, 0x74, 0x66, 0, 0, 0, 0]);
                for i in 0..9 {
                    let v = if i % 4 == 0 { 1.0f64 } else { 0.0 };
                    blob.extend_from_slice(&v.to_be_bytes());
                }
            }
            if offs[3] != 0 {
                blob.extend_from_slice(&[2u8; 16]);
                blob.extend_from_slice(&[1u8, 0, 0, 0]);
                blob.extend_from_slice(&[0x80u8; 8 * 3]);
            }
            if offs[4] != 0 && shape != 0 && shape != 6 {
                for _ in 0..3 {
                    blob.extend_from_slice(&[0x63u8, 0x75, 0x72, 0x76, 0, 0, 0, 0]);
                    blob.extend_from_slice(&2u32.to_be_bytes());
                    blob.extend_from_slice(&0x4000u16.to_be_bytes());
                    blob.extend_from_slice(&0x8000u16.to_be_bytes());
                }
            }
            let p = c::cmsCreateProfilePlaceholder(std::ptr::null_mut());
            c::cmsSetDeviceClass(p, 0x70727472);
            c::cmsSetColorSpace(p, 0x434D594B);
            c::cmsSetPCS(p, 0x4C616220);
            c::cmsSetProfileVersion(p, 4.4);
            c::cmsWriteRawTag(p, 0x42324130, blob.as_ptr() as *const _, blob.len() as u32);
            let mut buf = [0u8; 1 << 18];
            let mut nn = buf.len() as u32;
            let sv = c::cmsSaveProfileToMem(p, buf.as_mut_ptr() as *mut _, &mut nn);
            let pr = if sv != 0 {
                c::cmsOpenProfileFromMem(buf.as_ptr() as *const _, nn)
            } else {
                std::ptr::null_mut()
            };
            let rd = if !pr.is_null() {
                c::cmsReadTag(pr, 0x42324130)
            } else {
                std::ptr::null_mut()
            };
            eprintln!("mba {name} rd={}", !rd.is_null());
            if !pr.is_null() {
                c::cmsCloseProfile(pr);
            }
            c::cmsCloseProfile(p);
        }
    }
}

