/// cmstypes residual — MHC2 read tails via MHC2 mpet
///   tag with cvst+matf element combos + truncation.
#[test]
fn type_read78_arms() {
    unsafe {
        // MHC2 mpet: cvst + matf as 2 elements
        for (inch, outch, name) in [(3u16, 3u16, "33"), (1, 1, "11"), (4, 4, "44"), (2, 2, "22")] {
            let mut e1 = vec![0x63u8, 0x76, 0x73, 0x74, 0, 0, 0, 0];
            e1.extend_from_slice(&inch.to_be_bytes());
            e1.extend_from_slice(&0u16.to_be_bytes());
            let off = 12 + 8 * inch as u32;
            for _ in 0..inch {
                e1.extend_from_slice(&off.to_be_bytes());
                e1.extend_from_slice(&14u32.to_be_bytes());
            }
            for _ in 0..inch {
                e1.extend_from_slice(&[0x63u8, 0x75, 0x72, 0x76, 0, 0, 0, 0]);
                e1.extend_from_slice(&2u32.to_be_bytes());
                e1.extend_from_slice(&0x4000u16.to_be_bytes());
                e1.extend_from_slice(&0x8000u16.to_be_bytes());
            }
            let mut e2 = vec![0x6Du8, 0x61, 0x74, 0x66, 0, 0, 0, 0];
            e2.extend_from_slice(&inch.to_be_bytes());
            e2.extend_from_slice(&outch.to_be_bytes());
            let n = inch as usize * outch as usize;
            for i in 0..n {
                let v = if i % (outch as usize + 1) == 0 {
                    1.0f64
                } else {
                    0.0
                };
                e2.extend_from_slice(&v.to_be_bytes());
            }
            let mut blob = vec![0x6D, 0x70, 0x65, 0x74, 0, 0, 0, 0];
            blob.extend_from_slice(&inch.to_be_bytes());
            blob.extend_from_slice(&outch.to_be_bytes());
            blob.extend_from_slice(&2u32.to_be_bytes());
            blob.extend_from_slice(&24u32.to_be_bytes());
            blob.extend_from_slice(&(e1.len() as u32).to_be_bytes());
            blob.extend_from_slice(&(24 + e1.len() as u32).to_be_bytes());
            blob.extend_from_slice(&(e2.len() as u32).to_be_bytes());
            blob.extend_from_slice(&e1);
            blob.extend_from_slice(&e2);
            let p = c::cmsCreateProfilePlaceholder(std::ptr::null_mut());
            c::cmsSetDeviceClass(p, 0x6C696E6B);
            c::cmsSetColorSpace(p, 0x52474220);
            c::cmsSetPCS(p, 0x4C616220);
            c::cmsSetProfileVersion(p, 4.4);
            c::cmsWriteRawTag(p, 0x6D686332, blob.as_ptr() as *const _, blob.len() as u32);
            let mut buf = [0u8; 1 << 18];
            let mut nn = buf.len() as u32;
            let sv = c::cmsSaveProfileToMem(p, buf.as_mut_ptr() as *mut _, &mut nn);
            let pr = if sv != 0 {
                c::cmsOpenProfileFromMem(buf.as_ptr() as *const _, nn)
            } else {
                std::ptr::null_mut()
            };
            let rd = if !pr.is_null() {
                c::cmsReadTag(pr, 0x6D686332)
            } else {
                std::ptr::null_mut()
            };
            eprintln!("mhc2 {name} rd={}", !rd.is_null());
            if !pr.is_null() {
                c::cmsCloseProfile(pr);
            }
            c::cmsCloseProfile(p);
        }
    }
}

