/// cmstypes residual — MPE read tails: multi-element
///   chains with proper offset + mixed element types.
#[test]
fn type_read80_arms() {
    unsafe {
        // proper mpet: pos-table at 16 (after hdr),
        //   element bodies chained
        for nelem in [1u32, 2, 3] {
            let mut blob = vec![0x6D, 0x70, 0x65, 0x74, 0, 0, 0, 0];
            blob.extend_from_slice(&3u16.to_be_bytes());
            blob.extend_from_slice(&3u16.to_be_bytes());
            blob.extend_from_slice(&nelem.to_be_bytes());
            // pos-table starts at 16 (hdr 8 + io 4 +
            //   count 4)
            let mut elems = vec![];
            let mut off = 16 + 8 * nelem;
            for i in 0..nelem as usize {
                let ty = [0x63767374u32, 0x6D617466, 0x636C7574][i % 3];
                let mut e = vec![
                    (ty >> 24) as u8,
                    (ty >> 16) as u8,
                    (ty >> 8) as u8,
                    ty as u8,
                ];
                e.extend_from_slice(&[0, 0, 0, 0]);
                e.extend_from_slice(&3u16.to_be_bytes());
                e.extend_from_slice(&3u16.to_be_bytes());
                match ty {
                    0x63767374 => {
                        let o2: u32 = 12 + 8 * 3;
                        for _ in 0..3 {
                            e.extend_from_slice(&o2.to_be_bytes());
                            e.extend_from_slice(&14u32.to_be_bytes());
                        }
                        for _ in 0..3 {
                            e.extend_from_slice(&[0x63, 0x75, 0x72, 0x76, 0, 0, 0, 0]);
                            e.extend_from_slice(&2u32.to_be_bytes());
                            e.extend_from_slice(&0x4000u16.to_be_bytes());
                            e.extend_from_slice(&0x8000u16.to_be_bytes());
                        }
                    }
                    0x6D617466 => {
                        for i in 0..9 {
                            let v = if i % 4 == 0 { 1.0f64 } else { 0.0 };
                            e.extend_from_slice(&v.to_be_bytes());
                        }
                    }
                    _ => {
                        e.extend_from_slice(&[2u8; 16]);
                        e.extend_from_slice(&[1u8, 0, 0, 0]);
                        e.extend_from_slice(&[0x80u8; 8 * 3]);
                    }
                }
                blob.extend_from_slice(&off.to_be_bytes());
                blob.extend_from_slice(&(e.len() as u32).to_be_bytes());
                off += e.len() as u32;
                elems.push(e);
            }
            for e in &elems {
                blob.extend_from_slice(e);
            }
            let p = c::cmsCreateProfilePlaceholder(std::ptr::null_mut());
            c::cmsSetDeviceClass(p, 0x6C696E6B);
            c::cmsSetColorSpace(p, 0x52474220);
            c::cmsSetPCS(p, 0x4C616220);
            c::cmsSetProfileVersion(p, 4.4);
            c::cmsWriteRawTag(p, 0x44324230, blob.as_ptr() as *const _, blob.len() as u32);
            let mut buf = [0u8; 1 << 18];
            let mut nn = buf.len() as u32;
            let sv = c::cmsSaveProfileToMem(p, buf.as_mut_ptr() as *mut _, &mut nn);
            let pr = if sv != 0 {
                c::cmsOpenProfileFromMem(buf.as_ptr() as *const _, nn)
            } else {
                std::ptr::null_mut()
            };
            let rd = if !pr.is_null() {
                c::cmsReadTag(pr, 0x44324230)
            } else {
                std::ptr::null_mut()
            };
            eprintln!("mpet{nelem}elem rd={}", !rd.is_null());
            if !pr.is_null() {
                c::cmsCloseProfile(pr);
            }
            c::cmsCloseProfile(p);
        }
    }
}

