/// cmstypes residual — MPE curve/matrix read tails
///   via cvst + matf element variants on every class.
#[test]
fn type_read87_arms() {
    unsafe {
        // matf element at channel variants
        for (inch, outch, name) in [
            (1u16, 1u16, "11"),
            (3, 3, "33"),
            (4, 4, "44"),
            (2, 2, "22"),
            (3, 1, "31"),
            (1, 3, "13"),
            (8, 8, "88"),
            (15, 15, "1515"),
        ] {
            let mut e = vec![0x6Du8, 0x61, 0x74, 0x66, 0, 0, 0, 0];
            e.extend_from_slice(&inch.to_be_bytes());
            e.extend_from_slice(&outch.to_be_bytes());
            let n = inch as usize * outch as usize;
            for i in 0..n {
                let v = if i % (outch as usize + 1) == 0 {
                    1.0f64
                } else {
                    0.0
                };
                e.extend_from_slice(&v.to_be_bytes());
            }
            let mut blob = vec![0x6D, 0x70, 0x65, 0x74, 0, 0, 0, 0];
            blob.extend_from_slice(&inch.to_be_bytes());
            blob.extend_from_slice(&outch.to_be_bytes());
            blob.extend_from_slice(&1u32.to_be_bytes());
            blob.extend_from_slice(&24u32.to_be_bytes());
            blob.extend_from_slice(&(e.len() as u32).to_be_bytes());
            blob.extend_from_slice(&e);
            for cls in [0x6C696E6Bu32, 0x6D6E7472] {
                let p = c::cmsCreateProfilePlaceholder(std::ptr::null_mut());
                c::cmsSetDeviceClass(p, cls);
                c::cmsSetColorSpace(p, 0x52474220);
                c::cmsSetPCS(p, 0x4C616220);
                c::cmsSetProfileVersion(p, 4.4);
                c::cmsWriteRawTag(p, 0x44324230, blob.as_ptr() as *const _, blob.len() as u32);
                let mut buf = [0u8; 1 << 18];
                let mut nn = buf.len() as u32;
                let sv = c::cmsSaveProfileToMem(p, buf.as_mut_ptr() as *mut _, &mut nn);
                let pr = if sv != 0 {
                    c::cmsOpenProfileFromMem(buf.as_ptr() as *const _, nn)
                } else {
                    std::ptr::null_mut()
                };
                let rd = if !pr.is_null() {
                    c::cmsReadTag(pr, 0x44324230)
                } else {
                    std::ptr::null_mut()
                };
                if cls == 0x6C696E6B {
                    eprintln!("matf {name} rd={}", !rd.is_null());
                }
                if !pr.is_null() {
                    c::cmsCloseProfile(pr);
                }
                c::cmsCloseProfile(p);
            }
        }
        // matf channel edges
        for (i, o) in [(0u16, 0u16), (0xFFFF, 0xFFFF), (3, 0), (0, 3)] {
            let mut e = vec![0x6Du8, 0x61, 0x74, 0x66, 0, 0, 0, 0];
            e.extend_from_slice(&i.to_be_bytes());
            e.extend_from_slice(&o.to_be_bytes());
            let mut blob = vec![0x6D, 0x70, 0x65, 0x74, 0, 0, 0, 0];
            blob.extend_from_slice(&i.to_be_bytes());
            blob.extend_from_slice(&o.to_be_bytes());
            blob.extend_from_slice(&1u32.to_be_bytes());
            blob.extend_from_slice(&24u32.to_be_bytes());
            blob.extend_from_slice(&(e.len() as u32).to_be_bytes());
            blob.extend_from_slice(&e);
            let p = c::cmsCreateProfilePlaceholder(std::ptr::null_mut());
            c::cmsSetDeviceClass(p, 0x6C696E6B);
            c::cmsSetColorSpace(p, 0x52474220);
            c::cmsSetPCS(p, 0x4C616220);
            c::cmsSetProfileVersion(p, 4.4);
            c::cmsWriteRawTag(p, 0x44324230, blob.as_ptr() as *const _, blob.len() as u32);
            let mut buf = [0u8; 1 << 17];
            let mut nn = buf.len() as u32;
            let sv = c::cmsSaveProfileToMem(p, buf.as_mut_ptr() as *mut _, &mut nn);
            let pr = if sv != 0 {
                c::cmsOpenProfileFromMem(buf.as_ptr() as *const _, nn)
            } else {
                std::ptr::null_mut()
            };
            let rd = if !pr.is_null() {
                c::cmsReadTag(pr, 0x44324230)
            } else {
                std::ptr::null_mut()
            };
            eprintln!("matf {i}/{o} rd={}", !rd.is_null());
            if !pr.is_null() {
                c::cmsCloseProfile(pr);
            }
            c::cmsCloseProfile(p);
        }
    }
}

