/// cmstypes residual — LUT16 read tails via mft2
///   channel/precision/grid combos.
#[test]
fn type_read90_arms() {
    unsafe {
        for (inch, outch, prec, name) in [
            (3u8, 3u8, 2u8, "33p2"),
            (1, 1, 2, "11p2"),
            (4, 4, 2, "44p2"),
            (2, 2, 2, "22p2"),
            (3, 1, 2, "31p2"),
            (1, 3, 2, "13p2"),
            (3, 3, 1, "33p1"),
            (3, 3, 0, "33p0"),
            (3, 3, 255, "33pff"),
            (0, 3, 2, "0ch"),
            (3, 0, 2, "0ch-out"),
        ] {
            let mut blob = vec![0x6D, 0x66, 0x74, 0x32, 0, 0, 0, 0];
            blob.extend_from_slice(&inch.to_be_bytes());
            blob.extend_from_slice(&outch.to_be_bytes());
            blob.extend_from_slice(&[2u8, prec]);
            for i in 0..9 {
                let v = if i % 4 == 0 { 1.0f64 } else { 0.0 };
                blob.extend_from_slice(&v.to_be_bytes());
            }
            let npts = 8usize * outch as usize;
            let bpp = if prec == 1 {
                2
            } else if prec == 0 {
                1
            } else {
                2
            };
            for _ in 0..256 {
                blob.extend_from_slice(&0x8000u16.to_be_bytes());
            }
            for _ in 0..npts * bpp {
                blob.extend_from_slice(&[0x80u8]);
            }
            for _ in 0..256 {
                blob.extend_from_slice(&0x8000u16.to_be_bytes());
            }
            let p = c::cmsCreateProfilePlaceholder(std::ptr::null_mut());
            c::cmsSetDeviceClass(p, 0x6D6E7472);
            c::cmsSetColorSpace(p, 0x52474220);
            c::cmsSetPCS(p, 0x4C616220);
            c::cmsSetProfileVersion(p, 2.4);
            c::cmsWriteRawTag(p, 0x41324230, blob.as_ptr() as *const _, blob.len() as u32);
            let mut buf = [0u8; 1 << 18];
            let mut nn = buf.len() as u32;
            let sv = c::cmsSaveProfileToMem(p, buf.as_mut_ptr() as *mut _, &mut nn);
            let pr = if sv != 0 {
                c::cmsOpenProfileFromMem(buf.as_ptr() as *const _, nn)
            } else {
                std::ptr::null_mut()
            };
            let rd = if !pr.is_null() {
                c::cmsReadTag(pr, 0x41324230)
            } else {
                std::ptr::null_mut()
            };
            eprintln!("mft2 {name} rd={}", !rd.is_null());
            if !pr.is_null() {
                c::cmsCloseProfile(pr);
            }
            c::cmsCloseProfile(p);
        }
    }
}

