/// cmstypes residual — LUTA2B/LUTB2A read tails via
///   mft1/mft2 on every remaining class+tag.
#[test]
fn type_read103_arms() {
    unsafe {
        let mft1 = |inch: u8, outch: u8| {
            let mut b = vec![0x6D, 0x66, 0x74, 0x31, 0, 0, 0, 0];
            b.extend_from_slice(&inch.to_be_bytes());
            b.extend_from_slice(&outch.to_be_bytes());
            b.extend_from_slice(&[2u8, 0]);
            for i in 0..9 {
                let v = if i % 4 == 0 { 1.0f64 } else { 0.0 };
                b.extend_from_slice(&v.to_be_bytes());
            }
            for _ in 0..256 {
                b.extend_from_slice(&[0x80u8]);
            }
            for _ in 0..8 * outch as usize {
                b.extend_from_slice(&[0x80u8]);
            }
            for _ in 0..256 {
                b.extend_from_slice(&[0x80u8]);
            }
            b
        };
        let mft2 = |inch: u8, outch: u8| {
            let mut b = vec![0x6D, 0x66, 0x74, 0x32, 0, 0, 0, 0];
            b.extend_from_slice(&inch.to_be_bytes());
            b.extend_from_slice(&outch.to_be_bytes());
            b.extend_from_slice(&[2u8, 2]);
            for i in 0..9 {
                let v = if i % 4 == 0 { 1.0f64 } else { 0.0 };
                b.extend_from_slice(&v.to_be_bytes());
            }
            for _ in 0..256 {
                b.extend_from_slice(&0x8000u16.to_be_bytes());
            }
            for _ in 0..8 * outch as usize {
                b.extend_from_slice(&0x8000u16.to_be_bytes());
            }
            for _ in 0..256 {
                b.extend_from_slice(&0x8000u16.to_be_bytes());
            }
            b
        };
        for (cls, tag, inch, outch, name) in [
            (0x6D6E7472u32, 0x41324230, 3, 3, "mntr1-a2b"),
            (0x6D6E7472, 0x42324130, 3, 3, "mntr1-b2a"),
            (0x70727472, 0x41324230, 4, 3, "prtr1-a2b"),
            (0x70727472, 0x42324130, 3, 4, "prtr1-b2a"),
            (0x6C696E6B, 0x41324230, 3, 3, "link1-a2b"),
            (0x6C696E6B, 0x42324130, 3, 3, "link1-b2a"),
            (0x73706163, 0x41324230, 3, 3, "spac1-a2b"),
            (0x61627374, 0x41324230, 3, 3, "abst1-a2b"),
            (0x6E6D636C, 0x41324230, 3, 3, "nmcl1-a2b"),
            (0x6D6E7472u32, 0x41324230, 3, 3, "mntr2-a2b"),
            (0x70727472, 0x42324130, 3, 4, "prtr2-b2a"),
            (0x6C696E6B, 0x41324230, 3, 3, "link2-a2b"),
        ] {
            let blob = if name.ends_with("2-a2b") || name.ends_with("2-b2a") {
                mft2(inch, outch)
            } else {
                mft1(inch, outch)
            };
            let p = c::cmsCreateProfilePlaceholder(std::ptr::null_mut());
            c::cmsSetDeviceClass(p, cls);
            c::cmsSetColorSpace(p, 0x52474220);
            c::cmsSetPCS(p, 0x4C616220);
            c::cmsSetProfileVersion(p, 2.4);
            c::cmsWriteRawTag(p, tag, blob.as_ptr() as *const _, blob.len() as u32);
            let mut buf = [0u8; 1 << 18];
            let mut nn = buf.len() as u32;
            let sv = c::cmsSaveProfileToMem(p, buf.as_mut_ptr() as *mut _, &mut nn);
            let pr = if sv != 0 {
                c::cmsOpenProfileFromMem(buf.as_ptr() as *const _, nn)
            } else {
                std::ptr::null_mut()
            };
            let rd = if !pr.is_null() {
                c::cmsReadTag(pr, tag)
            } else {
                std::ptr::null_mut()
            };
            eprintln!("{name} rd={}", !rd.is_null());
            if !pr.is_null() {
                c::cmsCloseProfile(pr);
            }
            c::cmsCloseProfile(p);
        }
    }
}

