/// cmstypes residual — MPE read tails via `mpet`
///   element-types on every class+tag.
#[test]
fn type_read120_arms() {
    unsafe {
        for (elem_ty, name) in [
            (0x63767374u32, "cvst"),
            (0x6D617466u32, "matf"),
            (0x636C7574u32, "clut"),
            (0x62616373u32, "bacs"),
            (0x65616373u32, "eacs"),
        ] {
            let mut e = vec![
                (elem_ty >> 24) as u8,
                (elem_ty >> 16) as u8,
                (elem_ty >> 8) as u8,
                elem_ty as u8,
                0,
                0,
                0,
                0,
            ];
            e.extend_from_slice(&3u16.to_be_bytes());
            e.extend_from_slice(&3u16.to_be_bytes());
            match elem_ty {
                0x63767374 => {
                    let off: u32 = 12 + 8 * 3;
                    for _ in 0..3 {
                        e.extend_from_slice(&off.to_be_bytes());
                        e.extend_from_slice(&14u32.to_be_bytes());
                    }
                    for _ in 0..3 {
                        e.extend_from_slice(&[0x63u8, 0x75, 0x72, 0x76, 0, 0, 0, 0]);
                        e.extend_from_slice(&2u32.to_be_bytes());
                        e.extend_from_slice(&0x4000u16.to_be_bytes());
                        e.extend_from_slice(&0x8000u16.to_be_bytes());
                    }
                }
                0x6D617466 => {
                    for i in 0..9 {
                        let v = if i % 4 == 0 { 1.0f64 } else { 0.0 };
                        e.extend_from_slice(&v.to_be_bytes());
                    }
                }
                0x636C7574 => {
                    e.extend_from_slice(&[2u8; 16]);
                    e.extend_from_slice(&[1u8, 0, 0, 0]);
                    e.extend_from_slice(&[0x80u8; 8 * 3]);
                }
                _ => {
                    e.extend_from_slice(&[0x80u8; 16]);
                }
            }
            let mut blob = vec![0x6D, 0x70, 0x65, 0x74, 0, 0, 0, 0];
            blob.extend_from_slice(&3u16.to_be_bytes());
            blob.extend_from_slice(&3u16.to_be_bytes());
            blob.extend_from_slice(&1u32.to_be_bytes());
            blob.extend_from_slice(&24u32.to_be_bytes());
            blob.extend_from_slice(&(e.len() as u32).to_be_bytes());
            blob.extend_from_slice(&e);
            for tag in [
                0x44324230u32,
                0x44324231,
                0x44324232,
                0x44324233,
                0x6D686332,
            ] {
                let p = c::cmsCreateProfilePlaceholder(std::ptr::null_mut());
                c::cmsSetDeviceClass(p, 0x6D6E7472);
                c::cmsSetColorSpace(p, 0x52474220);
                c::cmsSetPCS(p, 0x4C616220);
                c::cmsSetProfileVersion(p, 4.4);
                c::cmsWriteRawTag(p, tag, blob.as_ptr() as *const _, blob.len() as u32);
                let mut buf = [0u8; 1 << 17];
                let mut nn = buf.len() as u32;
                let sv = c::cmsSaveProfileToMem(p, buf.as_mut_ptr() as *mut _, &mut nn);
                let pr = if sv != 0 {
                    c::cmsOpenProfileFromMem(buf.as_ptr() as *const _, nn)
                } else {
                    std::ptr::null_mut()
                };
                let rd = if !pr.is_null() {
                    c::cmsReadTag(pr, tag)
                } else {
                    std::ptr::null_mut()
                };
                if tag == 0x44324230 {
                    eprintln!("{name} rd={}", !rd.is_null());
                }
                if !pr.is_null() {
                    c::cmsCloseProfile(pr);
                }
                c::cmsCloseProfile(p);
            }
        }
    }
}

